
/**
 * Fortune War v1.5.28 — device-scoped online leaderboard.
 * Secrets are generated by WebCrypto and stored only as SHA-256 server hashes.
 * Browser sessions persist device_id + secret in localStorage, not hardware fingerprints.
 * No service-role credentials are ever returned to the client.
 */
const SUPABASE_URL=Deno.env.get("SUPABASE_URL")||"";
const SERVICE_ROLE=Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")||"";
const ALLOWED_ORIGIN="https://godujan.github.io";
const u8=new TextEncoder();
function cors(origin:string){
 return {
   "Access-Control-Allow-Origin":origin===ALLOWED_ORIGIN?origin:ALLOWED_ORIGIN,
   "Access-Control-Allow-Methods":"POST, OPTIONS",
   "Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type",
   "Vary":"Origin",
   "Content-Type":"application/json; charset=utf-8",
   "Cache-Control":"no-store"
 };
}
function respond(body:unknown,status=200,origin=ALLOWED_ORIGIN){
 return new Response(JSON.stringify(body),{status,headers:cors(origin)});
}
function fail(msg:string,code=400){throw {message:msg,status:code};}
const uuidRegex=/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i;
const secretRegex=/^[a-f0-9]{64}$/;
function validNick(value:unknown){
 if(typeof value!=="string")fail("닉네임을 입력하세요.");
 const v=(value as string).trim();
 if(v.length<2||v.length>16||!/^[\p{L}\p{N}_\- ]+$/u.test(v))fail("닉네임은 한글·영문·숫자 등 2~16자입니다.");
 return v;
}
function validUUID(value:unknown){
 if(typeof value!=="string"||!uuidRegex.test(value))fail("등록된 기기 계정이 없습니다.",401);
 return value as string;
}
function validSecret(value:unknown){
 if(typeof value!=="string"||!secretRegex.test(value))fail("기기 인증키를 확인하세요.",401);
 return value as string;
}
function fromHex(bytes:Uint8Array){return Array.from(bytes,x=>x.toString(16).padStart(2,"0")).join("");}
async function digest(token:string){
 const hash=await crypto.subtle.digest("SHA-256",u8.encode(token));
 return fromHex(new Uint8Array(hash));
}
function safeCompare(a:string,b:string){
 if(a.length!==b.length)return false;
 let acc=0;for(let i=0;i<a.length;i++)acc|=(a.charCodeAt(i)^b.charCodeAt(i));
 return acc===0;
}
async function rest(path:string,method="GET",body?:unknown){
 if(!SUPABASE_URL||!SERVICE_ROLE)throw new Error("Supabase server credentials are missing");
 const res=await fetch(SUPABASE_URL+"/rest/v1/"+path,{
  method,headers:{
   "apikey":SERVICE_ROLE,"Authorization":"Bearer "+SERVICE_ROLE,
   "Content-Type":"application/json",
   "Prefer":method==="POST"?"return=representation":"return=minimal"
  },
  body:body===undefined?undefined:JSON.stringify(body),
  signal:AbortSignal.timeout(9000)
 });
 if(!res.ok){const errorText=(await res.text()).slice(0,600);console.error("Device API storage:",res.status,errorText);throw new Error("랭킹 데이터 저장소 오류 ("+res.status+")")}
 if(method==="PATCH")return null;
 const text=await res.text();return text?JSON.parse(text):[];
}
async function authenticate(deviceId:unknown,secret:unknown){
 const id=validUUID(deviceId),token=validSecret(secret);
 const rows=await rest("fortune_device_players?select=id,nickname,token_hash,last_submit_at&id=eq."+encodeURIComponent(id)+"&limit=1");
 const item=Array.isArray(rows)?rows[0]:null;
 if(!item||!safeCompare(String(item.token_hash),await digest(token)))fail("이 기기의 온라인 계정 인증에 실패했습니다.",401);
 return item as {id:string,nickname:string,token_hash:string,last_submit_at:string|null};
}
const utcDayStart=(t:number)=>Math.floor(t/86400000)*86400000;
function koreaBounds(scope:string){
 const kst=Date.now()+9*3600000;
 const day=utcDayStart(kst);
 if(scope==="today")return {start:new Date(day-9*3600000).toISOString(),end:new Date(day+86400000-9*3600000).toISOString()};
 const epoch=Date.UTC(2026,10,6);
 const index=Math.floor((day-epoch)/(14*86400000));
 const start=epoch+index*14*86400000-9*3600000;
 return {start:new Date(start).toISOString(),end:new Date(start+14*86400000).toISOString()};
}
async function register(body:Record<string,unknown>){
 const nick=validNick(body.nickname);
 const tokenBytes=crypto.getRandomValues(new Uint8Array(32));
 const token=fromHex(tokenBytes);
 const hash=await digest(token);
 const id=crypto.randomUUID();
 await rest("fortune_device_players","POST",{id,nickname:nick,token_hash:hash});
 return {ok:true,device_id:id,device_secret:token,nickname:nick};
}
async function rename(body:Record<string,unknown>){
 const identity=await authenticate(body.device_id,body.device_secret);
 const nickname=validNick(body.nickname);
 if(identity.nickname!==nickname){
  await rest("fortune_device_players?id=eq."+encodeURIComponent(identity.id),"PATCH",{nickname,updated_at:new Date().toISOString()});
  await rest("fortune_device_runs?device_id=eq."+encodeURIComponent(identity.id),"PATCH",{nickname});
 }
 return {ok:true,device_id:identity.id,nickname};
}
async function submit(body:Record<string,unknown>){
 const user=await authenticate(body.device_id,body.device_secret);
 const difficulty=String(body.difficulty||"");
 if(difficulty!=="normal"&&difficulty!=="hard")fail("온라인 랭킹은 노멀·하드만 가능합니다.");
 const maxWave=difficulty==="normal"?60:80;
 const wave=Number(body.wave),kills=Number(body.kills),bestTier=Number(body.best_tier);
 if(!Number.isInteger(wave)||wave<1||wave>maxWave||
    !Number.isInteger(kills)||kills<0||kills>50000||
    !Number.isInteger(bestTier)||bestTier<0||bestTier>7)fail("전투 기록의 범위가 올바르지 않습니다.");
 const won=body.won===true && wave===maxWave;
 const now=Date.now();
 if(user.last_submit_at&&now-Date.parse(user.last_submit_at)<8000)fail("기록 저장 간격은 최소 8초입니다.",429);
 const levels:Record<string,number>={};
 for(const key of ["water","fire","ice","lightning","wind"]){
  const n=Number((body.element_levels as Record<string,unknown>|undefined)?.[key]??0);
  levels[key]=Math.max(0,Math.min(30,Number.isFinite(n)?Math.floor(n):0));
 }
 const score=wave*100+kills*3+(won?400:0);
 const row={device_id:user.id,nickname:user.nickname,difficulty,wave,kills,won,score,best_tier:bestTier,element_levels:levels,finished_at:new Date(now).toISOString()};
 await rest("fortune_device_runs","POST",row);
 await rest("fortune_device_players?id=eq."+encodeURIComponent(user.id),"PATCH",{last_submit_at:new Date(now).toISOString()});
 return {ok:true,score,mode:difficulty};
}
async function rankings(body:Record<string,unknown>){
 const scope=body.scope==="mine"?"mine":body.scope==="today"?"today":"season";
 const mode=body.difficulty==="normal"?"normal":"hard";
 let id="";
 let path="fortune_device_runs?select=device_id,nickname,score,wave,best_tier,element_levels,finished_at"
  +"&difficulty=eq."+mode;
 if(scope==="mine"){
  const user=await authenticate(body.device_id,body.device_secret);
  id=user.id;
  path+="&device_id=eq."+encodeURIComponent(id);
 }else{
  const bounds=koreaBounds(scope);
  path+="&finished_at=gte."+encodeURIComponent(bounds.start)+"&finished_at=lt."+encodeURIComponent(bounds.end);
 }
 path+="&order=score.desc,wave.desc,finished_at.asc&limit=1000";
 const rows=await rest(path);
 if(!Array.isArray(rows))throw new Error("Unexpected leaderboard response");
 const distinct=new Set<string>();
 const best=[];
 for(const r of rows){
  if(!r||typeof r.device_id!=="string"||distinct.has(r.device_id))continue;
  distinct.add(r.device_id);
  best.push({
    user_id:r.device_id,nickname:r.nickname,score:r.score,wave:r.wave,
    best_tier:r.best_tier,element_levels:r.element_levels,finished_at:r.finished_at
  });
  if(best.length>=100&&scope!=="mine")break;
 }
 return {ok:true,rows:best.map((r,index)=>({...r,rank:index+1})),scope,difficulty:mode};
}
Deno.serve(async(req:Request)=>{
 const origin=req.headers.get("origin")||"";
 if(req.method==="OPTIONS")return new Response(null,{status:204,headers:cors(origin)});
 if(req.method!=="POST")return respond({error:"POST only"},405,origin);
 if(origin!==ALLOWED_ORIGIN)return respond({error:"Origin not allowed"},403,origin);
 if(Number(req.headers.get("content-length")||0)>12000)return respond({error:"Request too large"},413,origin);
 try{
  const input=await req.json() as Record<string,unknown>;
  if(!input||typeof input!=="object"||Array.isArray(input))fail("잘못된 요청입니다.");
  let result;
  switch(input.action){
   case "register": result=await register(input);break;
   case "rename": result=await rename(input);break;
   case "submit": result=await submit(input);break;
   case "rankings": result=await rankings(input);break;
   default: fail("지원하지 않는 요청입니다.");
  }
  return respond(result,200,origin);
 }catch(err){
  const e=err as {message?:string,status?:number};
  const code=typeof e.status==="number"?e.status:500;
  if(code>=500)console.error("Device API:",String(e.message||e));
  return respond({ok:false,error:code>=500?"랭킹 서버 일시 오류입니다.":String(e.message||"요청 오류")},code,origin);
 }
});
